  add(a: Vec3, b: Vec3): Vec3;
  /** Component-wise difference **a − b**. */
  subtract(a: Vec3, b: Vec3): Vec3;
  scale(v: Vec3, s: number): Vec3;
  /** Signed scalar speed along \`forward\` (dot product); prefer unit forward from getForwardVector. */
